css:
.nairasim-container {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    max-width: 1080px;
    margin: 0 auto;
    padding: 24px;
    color: #f3efe2;
    background: radial-gradient(circle at 82% -10%, #1a5c46 0%, #0f3a2c 45%, #0a261d 100%);
    border-radius: 20px;
}

.nairasim-container * {
    box-sizing: border-box;
}

.nairasim-header {
    text-align: center;
    padding: 28px 22px 24px;
    background: linear-gradient(135deg, #0e3c2c 0%, #15573f 55%, #b9842b 165%);
    color: #fdf8ea;
    border-radius: 18px;
    margin-bottom: 20px;
    border: 1px solid #2a7a5a;
    box-shadow: 0 14px 36px rgba(0, 0, 0, 0.5);
    position: relative;
    overflow: hidden;
}

.nairasim-header::after {
    content: "";
    position: absolute;
    top: -40%;
    right: -8%;
    width: 240px;
    height: 240px;
    background: radial-gradient(circle, rgba(247, 183, 51, 0.22) 0%, rgba(247, 183, 51, 0) 70%);
    pointer-events: none;
}

.nairasim-header h1 {
    margin: 10px 0 12px;
    font-size: 2.4rem;
    font-weight: 800;
    letter-spacing: -0.5px;
    color: #ffffff;
}

.nairasim-header-tag {
    display: inline-block;
    font-size: 0.72rem;
    text-transform: uppercase;
    letter-spacing: 1.3px;
    font-weight: 700;
    color: #f7b733;
    background: rgba(247, 183, 51, 0.14);
    border: 1px solid rgba(247, 183, 51, 0.40);
    padding: 5px 15px;
    border-radius: 999px;
}

.nairasim-subtitle {
    margin: 0 auto;
    max-width: 810px;
    font-size: 1rem;
    line-height: 1.58;
    color: #dce9df;
}

.nairasim-period-counter {
    display: flex;
    align-items: center;
    gap: 8px;
    flex-wrap: wrap;
    font-size: 0.96rem;
    font-weight: 600;
    color: #bcd6c3;
    margin-bottom: 18px;
    padding: 6px 4px;
}

.nairasim-period-counter #currentDay,
.nairasim-period-counter #maxPeriods {
    font-weight: 800;
    color: #f7b733;
}

.nairasim-round-name {
    background: rgba(247, 183, 51, 0.16);
    color: #f7c75b;
    padding: 3px 13px;
    border-radius: 999px;
    font-size: 0.82rem;
    font-weight: 700;
    margin-left: 4px;
}

.nairasim-clock {
    margin-left: auto;
    font-size: 0.82rem;
    font-weight: 700;
    color: #ff9a52;
    background: rgba(255, 154, 82, 0.14);
    border: 1px solid rgba(255, 154, 82, 0.34);
    padding: 4px 13px;
    border-radius: 999px;
}

.nairasim-status-cards {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 14px;
    margin-bottom: 16px;
}

.nairasim-status-card {
    background: linear-gradient(160deg, #134434 0%, #0d3325 100%);
    border-radius: 16px;
    padding: 17px 16px 15px;
    border: 1px solid #245b46;
    box-shadow: 0 6px 20px rgba(0, 0, 0, 0.38);
    border-top: 4px solid #2a7a5a;
}

.nairasim-card-reach { border-top-color: #f7b733; }
.nairasim-card-active { border-top-color: #4fc1e9; }
.nairasim-card-contrib { border-top-color: #7ad19b; }
.nairasim-card-trust { border-top-color: #c08bff; }

.nairasim-label {
    font-size: 0.73rem;
    text-transform: uppercase;
    letter-spacing: 0.6px;
    font-weight: 700;
    color: #93b4a0;
}

.nairasim-value {
    font-size: 2.5rem;
    font-weight: 800;
    line-height: 1.1;
    margin: 4px 0 2px;
    color: #fdf8ea;
    font-variant-numeric: tabular-nums;
}

/* Inclusion Reach is the binding KPI — make it the loudest. */
.nairasim-card-reach .nairasim-value {
    font-size: 2.9rem;
    color: #ffcf5c;
    text-shadow: 0 0 18px rgba(247, 183, 51, 0.30);
}
.nairasim-card-active .nairasim-value { color: #6fd0f3; }
.nairasim-card-contrib .nairasim-value { color: #7ad19b; }
.nairasim-card-trust .nairasim-value { color: #c79bff; }

.nairasim-sublabel {
    font-size: 0.75rem;
    color: #87a795;
    line-height: 1.35;
}

.nairasim-contrib-negative .nairasim-value { color: #ff7d6b; }
.nairasim-contrib-positive .nairasim-value { color: #7ad19b; }
.nairasim-contrib-negative { border-top-color: #ff7d6b; }

.nairasim-reach-high { border-top-color: #ffcf5c; }
.nairasim-reach-low { border-top-color: #ff7d6b; }
.nairasim-reach-low .nairasim-value { color: #ff8c78; }

.nairasim-trust-low { border-top-color: #ff7d6b; }
.nairasim-trust-low .nairasim-value { color: #ff8c78; }

.nairasim-budget-bar {
    display: flex;
    justify-content: space-between;
    align-items: center;
    background: #0b2b20;
    border: 1px solid #245b46;
    color: #dce9df;
    padding: 11px 18px;
    border-radius: 13px;
    margin-bottom: 18px;
    font-weight: 700;
    font-size: 0.92rem;
}

.nairasim-budget-bar #budgetDisplay {
    font-size: 1.06rem;
    letter-spacing: 0.3px;
    color: #f7b733;
}

.nairasim-briefing {
    display: flex;
    gap: 14px;
    background: linear-gradient(160deg, #134434 0%, #0d3325 100%);
    border-left: 5px solid #f7b733;
    border-radius: 13px;
    padding: 17px 18px;
    margin-bottom: 18px;
    box-shadow: 0 6px 20px rgba(0, 0, 0, 0.32);
}

.nairasim-briefing-icon {
    font-size: 1.9rem;
    line-height: 1;
}

.nairasim-briefing-title {
    font-weight: 800;
    font-size: 1.1rem;
    color: #fdf8ea;
    margin-bottom: 6px;
}

.nairasim-briefing-text {
    font-size: 0.95rem;
    line-height: 1.58;
    color: #cfe0d4;
}

.nairasim-briefing-text strong { color: #f7c75b; }
.nairasim-briefing-text em { color: #ff9a52; font-style: italic; }

.nairasim-controls {
    background: linear-gradient(160deg, #103c2d 0%, #0c3224 100%);
    border-radius: 16px;
    padding: 20px 22px;
    margin-bottom: 18px;
    border: 1px solid #245b46;
    box-shadow: 0 6px 20px rgba(0, 0, 0, 0.32);
}

.nairasim-controls h3 {
    margin: 0 0 16px;
    font-size: 1.12rem;
    font-weight: 800;
    color: #fdf8ea;
    border-bottom: 2px solid #245b46;
    padding-bottom: 8px;
}

.nairasim-panel label {
    display: block;
    font-weight: 700;
    font-size: 0.92rem;
    color: #d7e6dc;
    margin: 15px 0 6px;
}

.nairasim-container select,
.nairasim-container input[type="number"] {
    width: 100%;
    padding: 10px 12px;
    border: 1px solid #2f6b51;
    border-radius: 10px;
    font-size: 0.92rem;
    background-color: #0c2d22;
    color: #f1f7f3;
    transition: border-color 0.15s, box-shadow 0.15s;
}

.nairasim-container select:focus,
.nairasim-container input[type="number"]:focus {
    outline: none;
    border-color: #f7b733;
    box-shadow: 0 0 0 3px rgba(247, 183, 51, 0.20);
}

.nairasim-container select option {
    background-color: #0c2d22;
    color: #f1f7f3;
}

.nairasim-container input[type="range"] {
    width: 100%;
    margin: 8px 0 2px;
    accent-color: #f7b733;
}

.nairasim-range-readout,
.nairasim-alloc-readout {
    font-size: 0.86rem;
    font-weight: 700;
    color: #93b4a0;
    margin-top: 6px;
    line-height: 1.4;
}

.nairasim-alloc-readout span:nth-child(2) {
    color: #f7b733;
    font-weight: 800;
}

.nairasim-hint {
    font-size: 0.8rem;
    color: #87a795;
    margin-top: 5px;
    line-height: 1.45;
}

.nairasim-alloc-grid {
    display: flex;
    flex-direction: column;
    gap: 8px;
    margin-top: 4px;
}

.nairasim-alloc-row {
    display: flex;
    align-items: center;
    gap: 12px;
    background: #0c2d22;
    border: 1px solid #2a5f49;
    border-radius: 10px;
    padding: 9px 12px;
}

.nairasim-alloc-name {
    flex: 1;
    font-size: 0.87rem;
    font-weight: 600;
    color: #d7e6dc;
}

.nairasim-alloc-row input[type="number"] {
    width: 92px;
    flex: 0 0 92px;
}

.nairasim-container .btn {
    margin-top: 18px;
    font-weight: 700;
}

.nairasim-container .btn-primary {
    background: linear-gradient(135deg, #b9842b 0%, #f7b733 100%);
    border: none;
    color: #2a1a02;
    padding: 11px 28px;
    border-radius: 10px;
    box-shadow: 0 8px 22px rgba(185, 132, 43, 0.45);
}

.nairasim-container .btn-primary:hover {
    filter: brightness(1.06);
}

.nairasim-container .btn-outline-secondary {
    margin-left: 10px;
    border-color: #2f6b51;
    color: #93b4a0;
    background: transparent;
}

.nairasim-coach {
    background: linear-gradient(160deg, #0b2b20 0%, #1c2410 100%);
    color: #e3eee6;
    border: 1px solid #4a5a26;
    border-radius: 16px;
    padding: 16px 20px;
    margin-bottom: 18px;
    box-shadow: 0 6px 20px rgba(0, 0, 0, 0.32);
}

.nairasim-coach-header {
    font-size: 0.77rem;
    text-transform: uppercase;
    letter-spacing: 1px;
    font-weight: 700;
    color: #f7b733;
    margin-bottom: 8px;
}

.nairasim-coach-body {
    font-size: 0.95rem;
    line-height: 1.58;
}

.nairasim-coach-body strong { color: #f7c75b; }
.nairasim-coach-body em { color: #ff9a52; font-style: italic; }

.nairasim-history,
.nairasim-chart {
    background: linear-gradient(160deg, #103c2d 0%, #0c3224 100%);
    border-radius: 16px;
    padding: 18px 20px;
    margin-bottom: 18px;
    border: 1px solid #245b46;
    box-shadow: 0 6px 20px rgba(0, 0, 0, 0.32);
}

.nairasim-history h3,
.nairasim-chart h3 {
    margin: 0 0 14px;
    font-size: 1.08rem;
    font-weight: 800;
    color: #fdf8ea;
}

.nairasim-container table#usfHistoryTable {
    width: 100%;
    font-size: 0.87rem;
    color: #d7e6dc;
}

.nairasim-container table#usfHistoryTable th {
    background: #0c2d22;
    color: #f7b733;
    font-weight: 700;
    text-transform: uppercase;
    font-size: 0.71rem;
    letter-spacing: 0.4px;
    padding: 8px 10px;
    border-bottom: 2px solid #2a5f49;
}

.nairasim-container table#usfHistoryTable td {
    padding: 8px 10px;
    border-bottom: 1px solid #1c4233;
    color: #cfe0d4;
}

.nairasim-container table#usfHistoryTable tr:nth-child(even) td {
    background: #0d3527;
}

.nairasim-chart canvas {
    max-width: 100%;
}

@media (max-width: 768px) {
    .nairasim-container {
        padding: 14px;
    }
    .nairasim-header h1 {
        font-size: 1.75rem;
    }
    .nairasim-status-cards {
        grid-template-columns: repeat(2, 1fr);
        gap: 10px;
    }
    .nairasim-value {
        font-size: 2rem;
    }
    .nairasim-card-reach .nairasim-value {
        font-size: 2.3rem;
    }
    .nairasim-clock {
        margin-left: 0;
    }
    .nairasim-period-counter {
        font-size: 0.88rem;
    }
    .nairasim-budget-bar {
        flex-direction: column;
        gap: 4px;
        align-items: flex-start;
    }
    .nairasim-alloc-row {
        flex-wrap: wrap;
    }
    .nairasim-alloc-row input[type="number"] {
        width: 100%;
        flex: 1 1 100%;
    }
    .nairasim-container .btn-outline-secondary {
        margin-left: 0;
        margin-top: 8px;
        display: block;
        width: 100%;
    }
}


/* v1.1.0 completion-message card (appended; dark-on-light, self-contained) */
.nairasim-cm { background:#f5faf7; color:#12211a; border-radius:14px; padding:22px 24px; max-width:640px; margin:0 auto; font-family:inherit; box-shadow:0 8px 30px rgba(0,0,0,0.18); }
.nairasim-cm-head { text-align:center; border-bottom:1px solid #d9e7df; padding-bottom:14px; margin-bottom:16px; }
.nairasim-cm-title { font-size:13px; letter-spacing:.08em; text-transform:uppercase; color:#54685c; font-weight:700; }
.nairasim-cm-scorewrap { margin:8px 0 2px; }
.nairasim-cm-score { font-size:52px; font-weight:800; color:#0f8a52; line-height:1; }
.nairasim-cm-score-max { font-size:20px; color:#82948a; font-weight:600; }
.nairasim-cm-grade { font-size:19px; font-weight:700; color:#12211a; margin-top:4px; }
.nairasim-cm-badges { margin-top:12px; display:flex; flex-wrap:wrap; gap:8px; justify-content:center; }
.nairasim-cm-badge { font-size:12px; font-weight:700; padding:4px 11px; border-radius:999px; }
.nairasim-cm-met { background:#d0f0df; color:#0c6b42; }
.nairasim-cm-fail { background:#fce0dc; color:#a4322a; }
.nairasim-cm-metrics { display:flex; flex-wrap:wrap; gap:12px; justify-content:center; margin-bottom:16px; }
.nairasim-cm-metric { background:#e9f2ec; border-radius:10px; padding:12px 16px; min-width:104px; text-align:center; }
.nairasim-cm-metric-val { font-size:22px; font-weight:800; color:#12211a; }
.nairasim-cm-metric-lbl { font-size:11px; letter-spacing:.05em; text-transform:uppercase; color:#54685c; margin-top:3px; }
.nairasim-cm-insights { background:#e9f2ec; border-radius:10px; padding:14px 18px; }
.nairasim-cm-insights-title { font-size:12px; letter-spacing:.06em; text-transform:uppercase; color:#54685c; font-weight:700; margin-bottom:8px; }
.nairasim-cm-insights ul { margin:0; padding-left:18px; }
.nairasim-cm-insights li { font-size:14px; line-height:1.5; color:#293830; margin-bottom:7px; }

