(function() {
    'use strict';

    class NairaReachAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = `Banking the Unbanked`;
            this.version = `1.1.0`;

            this.ROUNDS = [
                { id: 1, titleKey: `briefing_title_r1`, textKey: `briefing_text_r1`, panelId: `round1Panel`, nameKey: `round_name_r1`, clockKey: `clock_r1` },
                { id: 2, titleKey: `briefing_title_r2`, textKey: `briefing_text_r2`, panelId: `round2Panel`, nameKey: `round_name_r2`, clockKey: `clock_r2` },
                { id: 3, titleKey: `briefing_title_r3`, textKey: `briefing_text_r3`, panelId: `round3Panel`, nameKey: `round_name_r3`, clockKey: `clock_r3` },
                { id: 4, titleKey: `briefing_title_r4`, textKey: `briefing_text_r4`, panelId: `round4Panel`, nameKey: `round_name_r4`, clockKey: `clock_r4` }
            ];

            // ---- Numbers reference card (NairaReach Financial Technologies Ltd.) ----
            this.COST_TO_SERVE = 2100;       // NGN/user/year fully loaded acquire + serve
            this.LAUNCH_BUDGET = 1.2;        // NGN 1.2B Round-2 launch budget
            this.TRANCHE = 4.5;              // NGN 4.5B inclusion-contingent tranche
            this.COMM_MIN = 15;              // agent commission floor (NGN/txn)
            this.COMM_MAX = 60;              // agent commission ceiling (NGN/txn)

            // ---- Concept "truths" the math rewards (the genuinely-excluded play) ----
            this.TRUE_SEGMENT = `marketwomen`;   // deeply/under-served, reachable near retailers; farmers also strong
            this.TRUE_CHANNEL = `ussd_agent`;    // feature-phone reality
            this.TRUE_PRICING = `float_subsidized`;
            this.TRUE_KYC = `tier1`;

            // Per-segment profile: inclusion = % previously-unbanked the segment moves;
            // smartphone = share that can open an app; reach = how addressable they are.
            this.SEGMENTS = {
                farmers:     { inclusion: 0.90, smartphone: 0.25, baseUsers: 320000, distant: true,  feasibility: 0.80 },
                marketwomen: { inclusion: 0.82, smartphone: 0.40, baseUsers: 380000, distant: true,  feasibility: 0.95 },
                riders:      { inclusion: 0.30, smartphone: 0.85, baseUsers: 450000, distant: false, feasibility: 1.00 },
                traders:     { inclusion: 0.22, smartphone: 0.70, baseUsers: 500000, distant: false, feasibility: 1.00 },
                students:    { inclusion: 0.08, smartphone: 0.80, baseUsers: 300000, distant: false, feasibility: 1.00 }
            };
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    reach: 8,                 // % of new users previously unbanked (binding board KPI)
                    activeUsers: 0,           // new monthly-active accounts reached (thousands)
                    contribution: -1200,      // NGN/year net contribution per active user
                    trust: 25,                // agent-network & community confidence (0-100)
                    budgetUsed: 0,            // NGN B of the 1.2B launch budget committed
                    revenuePerUser: 0,        // NGN/year gross revenue per active user
                    bankedTheBanked: false,
                    channelMismatch: false,
                    agentStarved: false,
                    burningCash: false,
                    funnelCollapsed: false,
                    reachHistory: [8],
                    trustHistory: [25],
                    contribHistory: [-1200],
                    activeHistory: [0],
                    lastCoach: ``
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                // Deliberately middling/wrong-leaning seed so a blind click-through cannot auto-win:
                // an easy banked-ish segment on an app-only channel with a monthly fee and full KYC.
                state.decisions = {
                    segment: `riders`,
                    job: `send`,
                    barrier: `cost`,
                    channel: `app_only`,
                    agentModel: `owned`,
                    commission: 35,
                    float: 0.30,
                    recruit: 0.30,
                    channelBuild: 0.30,
                    education: 0.30,
                    pricing: `monthly_fee`,
                    price: 40,
                    kyc: `tier3`,
                    txn: 8,
                    shock: `pivot`,
                    proof: `topline`,
                    tradeoff: `take`,
                    conviction: 50
                };
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            const state = window.mySimulation.state;
            const round = state.currentPeriod || 1;
            const warn = (k) => window.mySimulation.uiManager.showNotification(window.mySimulation.t(k), `warning`);

            if (round === 1) {
                const sg = document.getElementById(`segmentInput`);
                const jb = document.getElementById(`jobInput`);
                const ba = document.getElementById(`barrierInput`);
                if (sg) decisions.segment = sg.value;
                if (jb) decisions.job = jb.value;
                if (ba) decisions.barrier = ba.value;
                if (!decisions.segment) { warn(`warn_segment`); return false; }
            } else if (round === 2) {
                const ch = document.getElementById(`channelInput`);
                const am = document.getElementById(`agentModelInput`);
                const cm = document.getElementById(`commissionInput`);
                const fl = document.getElementById(`floatInput`);
                const rc = document.getElementById(`recruitInput`);
                const cb = document.getElementById(`channelBuildInput`);
                const ed = document.getElementById(`educationInput`);
                if (ch) decisions.channel = ch.value;
                if (am) decisions.agentModel = am.value;
                if (cm) decisions.commission = parseInt(cm.value, 10);
                if (fl) decisions.float = parseFloat(fl.value);
                if (rc) decisions.recruit = parseFloat(rc.value);
                if (cb) decisions.channelBuild = parseFloat(cb.value);
                if (ed) decisions.education = parseFloat(ed.value);

                if (!Number.isFinite(decisions.commission) || decisions.commission < this.COMM_MIN || decisions.commission > this.COMM_MAX) {
                    warn(`warn_commission_range`); return false;
                }
                const parts = [decisions.float, decisions.recruit, decisions.channelBuild, decisions.education];
                if (parts.some((v) => !Number.isFinite(v) || v < 0)) {
                    warn(`warn_alloc_negative`); return false;
                }
                const total = Math.round((decisions.float + decisions.recruit + decisions.channelBuild + decisions.education) * 100) / 100;
                if (Math.abs(total - this.LAUNCH_BUDGET) > 0.001) {
                    warn(`warn_alloc_total`); return false;
                }
            } else if (round === 3) {
                const pr = document.getElementById(`pricingInput`);
                const pc = document.getElementById(`priceInput`);
                const ky = document.getElementById(`kycInput`);
                const tx = document.getElementById(`txnInput`);
                if (pr) decisions.pricing = pr.value;
                if (pc) decisions.price = parseFloat(pc.value);
                if (ky) decisions.kyc = ky.value;
                if (tx) decisions.txn = parseInt(tx.value, 10);
                if (!Number.isFinite(decisions.price) || decisions.price < 0 || decisions.price > 200) {
                    warn(`warn_price_range`); return false;
                }
                if (!Number.isFinite(decisions.txn) || decisions.txn < 1 || decisions.txn > 30) {
                    warn(`warn_txn_range`); return false;
                }
            } else if (round === 4) {
                const sh = document.getElementById(`shockInput`);
                const pf = document.getElementById(`proofInput`);
                const td = document.getElementById(`tradeoffInput`);
                const cv = document.getElementById(`convictionInput`);
                if (sh) decisions.shock = sh.value;
                if (pf) decisions.proof = pf.value;
                if (td) decisions.tradeoff = td.value;
                if (cv) decisions.conviction = parseInt(cv.value, 10);
                if (!Number.isFinite(decisions.conviction) || decisions.conviction < 0 || decisions.conviction > 100) {
                    warn(`warn_conviction_range`); return false;
                }
            }
            // Keep the per-round briefing in sync once the inputs validate.
            this._updateBriefing(state);
            return true;
        }

        calculateResults(state) {
            const d = state.decisions;
            const ds = state.domainState;
            const round = state.currentPeriod;

            let reachDelta = 0, trustDelta = 0, coachKey = `coach_default`, summaryKey = `sum_default`;

            if (round === 1) {
                // DIAGNOSE — segment choice sets the binding inclusion KPI.
                const seg = this.SEGMENTS[d.segment] || this.SEGMENTS.riders;
                // Inclusion reach is anchored to the chosen segment's previously-unbanked share.
                const targetReach = Math.round(seg.inclusion * 100);
                ds.reach = Math.round(ds.reach + (targetReach - ds.reach) * 0.85);

                if (seg.inclusion >= 0.70) {
                    trustDelta += 8; coachKey = `coach_r1_excluded`;
                    ds.bankedTheBanked = false;
                } else if (seg.inclusion >= 0.30) {
                    trustDelta -= 2; coachKey = `coach_r1_mixed`;
                    ds.bankedTheBanked = false;
                } else {
                    // Banking the banked — Common Error 1 / decision-tree branch 1.
                    trustDelta -= 6; coachKey = `coach_r1_banked`;
                    ds.bankedTheBanked = true;
                }

                // The "job to be done" and the named barrier sharpen (or muddy) the diagnosis.
                if (d.job === `save` || d.job === `send`) trustDelta += 3;
                if (d.barrier === `trust` || d.barrier === `documentation` || d.barrier === `distance`) {
                    trustDelta += 3;
                    if (!ds.bankedTheBanked && coachKey === `coach_r1_excluded`) coachKey = `coach_r1_sharp`;
                } else if (d.barrier === `cost`) {
                    trustDelta += 1;
                }

                summaryKey = ds.bankedTheBanked ? `sum_r1_banked` : (seg.inclusion >= 0.70 ? `sum_r1_good` : `sum_r1_weak`);
            } else if (round === 2) {
                // DESIGN the channel & agent model for the feature-phone reality.
                const seg = this.SEGMENTS[d.segment] || this.SEGMENTS.riders;

                // Channel-reality match (decision-tree branch 2): an app-only build excludes
                // the feature-phone majority. USSD+agents reaches everyone.
                let channelReach = 1.0;
                if (d.channel === `ussd_agent`) {
                    channelReach = 1.0; trustDelta += 6; ds.channelMismatch = false;
                    coachKey = `coach_r2_ussd`;
                } else if (d.channel === `app_agent`) {
                    channelReach = 0.62 + seg.smartphone * 0.38; trustDelta += 1; ds.channelMismatch = false;
                    coachKey = `coach_r2_appagent`;
                } else { // app_only
                    channelReach = seg.smartphone; ds.channelMismatch = true;
                    trustDelta -= 4; coachKey = `coach_r2_apponly`;
                }

                // Agent model: shared retail = low fixed cost + instant trust; owned = high cost, slow.
                let agentTrust = 0, agentCostFactor = 1.0;
                if (d.agentModel === `retail`) { agentTrust = 8; agentCostFactor = 0.7; }
                else if (d.agentModel === `superagent`) { agentTrust = 4; agentCostFactor = 0.85; }
                else { agentTrust = 2; agentCostFactor = 1.3; } // owned
                trustDelta += agentTrust;

                // Budget allocation: float = the trust backbone (decision-tree branch 6);
                // education converts a bank-skeptical user; recruitment buys agent density.
                const floatShare = d.float / this.LAUNCH_BUDGET;
                const eduShare = d.education / this.LAUNCH_BUDGET;
                const recruitShare = d.recruit / this.LAUNCH_BUDGET;

                if (d.float < 0.20) { trustDelta -= 10; ds.agentStarved = true; coachKey = `coach_r2_nofloat`; }
                else if (d.float >= 0.30) { trustDelta += 6; }
                trustDelta += Math.round(eduShare * 10) + Math.round(recruitShare * 6);

                // Commission must keep agents active but not eat all the revenue (links R2->R3).
                if (d.commission < 20) { trustDelta -= 6; }
                else if (d.commission >= 25 && d.commission <= 45) { trustDelta += 3; }

                // Density / reachable population this plan can actually touch (stored as thousands).
                const density = 0.55 + recruitShare * 0.5;
                ds.activeUsers = Math.round((seg.baseUsers * channelReach * Math.min(1, density) * seg.feasibility) / 1000);

                ds.budgetUsed = Math.min(this.LAUNCH_BUDGET, Math.round((d.float + d.recruit + d.channelBuild + d.education) * 100) / 100);

                if (ds.channelMismatch) summaryKey = `sum_r2_mismatch`;
                else if (ds.agentStarved) summaryKey = `sum_r2_nofloat`;
                else if (d.channel === `ussd_agent` && d.float >= 0.30) summaryKey = `sum_r2_good`;
                else summaryKey = `sum_r2_weak`;
            } else if (round === 3) {
                // PRICING under the affordability constraint — the coupled fee/agent/KYC system.
                // KYC tier sets the onboarding funnel AND the per-user transaction headroom.
                let funnel = 1.0, kycTxnCap = 30;
                if (d.kyc === `tier1`) { funnel = 1.0; kycTxnCap = 12; }
                else if (d.kyc === `tier2`) { funnel = 0.85; kycTxnCap = 22; }
                else { funnel = 0.45; kycTxnCap = 30; ds.funnelCollapsed = true; } // tier3 blocks the undocumented

                if (d.kyc === `tier3`) { trustDelta -= 6; coachKey = `coach_r3_kyc`; }
                else if (d.kyc === `tier1`) { trustDelta += 4; }

                const effectiveTxn = Math.min(d.txn, kycTxnCap);

                // Effective per-transaction revenue the COMPANY keeps depends on the pricing model.
                // A monthly fee on a user who rejects fixed fees collapses adoption (branch 3).
                // Affordability adoption multiplier: how many of the assumed transactions actually
                // happen given how the price lands on a NGN 45,000/month wallet.
                let monthlyFeePenalty = false;
                let perTxnRevenue = 0;       // NGN the COMPANY keeps per transaction
                let adoption = 1.0;          // share of assumed transactions that actually occur
                if (d.pricing === `monthly_fee`) {
                    // Fixed fee on a fee-averse wallet — most users churn, the rest transact little.
                    monthlyFeePenalty = true;
                    perTxnRevenue = 4;
                    adoption = 0.30;
                    trustDelta -= 10; coachKey = `coach_r3_monthly`;
                } else if (d.pricing === `flat_fee`) {
                    // Charging the poor directly: every Naira of the flat fee suppresses usage.
                    perTxnRevenue = d.price * 0.7;
                    adoption = Math.max(0.35, 1.15 - d.price / 60);   // ₦20→0.82, ₦40→0.48, ₦60→0.35
                } else if (d.pricing === `pct_capped`) {
                    perTxnRevenue = d.price * 0.6;
                    adoption = Math.max(0.55, 1.05 - d.price / 100);
                    trustDelta += 2;
                } else { // float_subsidized — free/low P2P, monetise float + airtime + bill-pay margins
                    // The headline price stays affordable; the company earns on the MOVEMENT of money
                    // (float interest on aggregated balances, airtime & bill-pay margins) regardless
                    // of a low headline fee. Affordable pricing keeps adoption high.
                    perTxnRevenue = d.price * 0.45 + 16;
                    adoption = 1.0;
                    trustDelta += 6;
                }

                // The agent is paid out of the same fee, but the commission only applies to the
                // cash-in / cash-out leg an agent actually handles (~42% of transactions); pure
                // digital P2P, airtime and bill-pay don't touch an agent.
                const AGENT_TXN_SHARE = 0.42;

                // If the headline price is below the Round-2 commission, the agent earns nothing on
                // the cash leg and the network collapses (branch 3). Float-subsidized is the one model
                // where the float pool, not the customer fee, funds the agent — so it is exempt.
                if (d.price < d.commission && d.pricing !== `float_subsidized`) {
                    ds.agentStarved = true; trustDelta -= 12; coachKey = `coach_r3_starve`;
                }
                // A high fixed/flat fee on a NGN 45,000/month wallet drives the customer away.
                if ((d.pricing === `flat_fee` || d.pricing === `pct_capped`) && d.price > 50) {
                    trustDelta -= 6; if (coachKey === `coach_default`) coachKey = `coach_r3_toohigh`;
                }

                // Unit economics: revenue/user/year vs the NGN 2,100 cost-to-serve, net of agent cost.
                const realTxn = effectiveTxn * adoption;
                const grossRev = Math.round(perTxnRevenue * realTxn * 12 * funnel);
                const agentCostYr = Math.round(d.commission * realTxn * AGENT_TXN_SHARE * 12 * funnel);
                // Shared retail + USSD engineer cost-to-serve DOWN; owned agents + app push it up.
                let serveCost = this.COST_TO_SERVE;
                if (d.channel === `ussd_agent`) serveCost -= 500;
                if (d.agentModel === `retail`) serveCost -= 350;
                else if (d.agentModel === `owned`) serveCost += 400;
                serveCost = Math.max(700, serveCost);

                ds.revenuePerUser = grossRev;
                ds.contribution = Math.round(grossRev - agentCostYr - serveCost);

                // Reaching real excluded users while contribution stays negative = burning cash (branch 4).
                if (ds.contribution < 0 && !ds.bankedTheBanked && ds.reach >= 50) {
                    ds.burningCash = true;
                    if (coachKey === `coach_default`) coachKey = `coach_r3_burn`;
                } else {
                    ds.burningCash = false;
                }

                if (coachKey === `coach_default`) {
                    coachKey = (ds.contribution >= 0 && d.pricing === `float_subsidized`) ? `coach_r3_sustainable` : `coach_r3_mixed`;
                }

                if (monthlyFeePenalty || ds.agentStarved) summaryKey = `sum_r3_priced`;
                else if (ds.contribution >= 0) summaryKey = `sum_r3_good`;
                else summaryKey = `sum_r3_weak`;
            } else if (round === 4) {
                // RECOVER & SCALE — absorb the shock without abandoning the mandate; pitch the tranche.
                switch (d.shock) {
                    case `liquidity`: trustDelta += 10; coachKey = `coach_r4_liquidity`; break;
                    case `competitor`: trustDelta += 6; coachKey = `coach_r4_competitor`; break;
                    case `caps`: trustDelta += 5; coachKey = `coach_r4_caps`; break;
                    case `pivot`:
                        // Abandoning the mandate for easy urban growth fails the milestone (branch 1).
                        trustDelta -= 10; ds.bankedTheBanked = true;
                        ds.reach = Math.round(ds.reach * 0.55);
                        coachKey = `coach_r4_pivot`; break;
                }

                switch (d.proof) {
                    case `cohort`: trustDelta += 12; break;
                    case `topline`: trustDelta -= 4; coachKey = `coach_r4_topline`; break;
                    case `charity`: trustDelta -= 6; coachKey = `coach_r4_charity`; break;
                }

                switch (d.tradeoff) {
                    case `hold`: trustDelta += 8; break;
                    case `hybrid`: trustDelta += 3; break;
                    case `take`: trustDelta -= 8; ds.bankedTheBanked = true; coachKey = `coach_r4_take`; break;
                }

                if (d.conviction >= 60) trustDelta += 4;
                else if (d.conviction <= 25) trustDelta -= 4;

                if (d.shock !== `pivot` && d.proof === `cohort` && d.tradeoff !== `take`) {
                    coachKey = `coach_r4_pitch`;
                    summaryKey = `sum_r4_good`;
                } else {
                    summaryKey = `sum_r4_weak`;
                }
            }

            // Apply deltas. Reach & trust are 0-100; contribution & activeUsers carried as-is.
            ds.reach = Math.max(0, Math.min(100, Math.round(ds.reach)));
            ds.trust = Math.max(0, Math.min(100, Math.round(ds.trust + trustDelta)));

            ds.reachHistory.push(ds.reach);
            ds.trustHistory.push(ds.trust);
            ds.contribHistory.push(ds.contribution);
            ds.activeHistory.push(ds.activeUsers);

            const coachMsg = window.mySimulation.t(coachKey);
            ds.lastCoach = coachMsg;
            const coachEl = document.getElementById(`coachText`);
            if (coachEl) coachEl.innerHTML = coachMsg;

            // v1.1.0 fix: persist instructor-card composite to domainState every period.
            if (!ds.performance) ds.performance = {};
            ds.performance.overallScore = this._composite(ds);

            const self = this;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: state.currentPeriod + 1 });
            }, 500);

            return {
                period: state.currentPeriod,
                reach: ds.reach,
                reachDelta: Math.round(reachDelta),
                activeUsers: ds.activeUsers,
                contribution: ds.contribution,
                revenuePerUser: ds.revenuePerUser,
                trust: ds.trust,
                trustDelta: Math.round(trustDelta),
                budgetUsed: ds.budgetUsed,
                bankedTheBanked: ds.bankedTheBanked,
                channelMismatch: ds.channelMismatch,
                agentStarved: ds.agentStarved,
                burningCash: ds.burningCash,
                summary: window.mySimulation.t(summaryKey),
                coach: coachMsg
            };
        }

        _fmtNaira(v) {
            // Nigerian Naira. English "₦1,200" (symbol before, comma thousands);
            // Spanish "1.200 ₦" (symbol after, dot thousands).
            const lang = (window.mySimulation && window.mySimulation.language) ? window.mySimulation.language : `en`;
            const sign = v < 0 ? `-` : ``;
            const abs = Math.round(Math.abs(v));
            if (lang === `es`) {
                const grouped = abs.toLocaleString(`de-DE`);
                return `${sign}${grouped} ₦`;
            }
            const grouped = abs.toLocaleString(`en-US`);
            return `${sign}₦${grouped}`;
        }

        _fmtNairaB(v) {
            const lang = (window.mySimulation && window.mySimulation.language) ? window.mySimulation.language : `en`;
            const num = Number(v).toFixed(2);
            if (lang === `es`) {
                return `${num.replace(`.`, `,`)} B ₦`;
            }
            return `₦${num}B`;
        }

        setupUI(uiManager) {
            uiManager.bind(`currentDay`, `currentPeriod`);
            uiManager.bind(`maxPeriods`, `maxPeriods`);

            const self = this;

            uiManager.bind(`reachDisplay`, `domainState.reach`, (v) => {
                const card = document.querySelector(`.nairasim-card-reach`);
                if (card) {
                    card.classList.toggle(`nairasim-reach-high`, Number(v) >= 60);
                    card.classList.toggle(`nairasim-reach-low`, Number(v) < 30);
                }
                return Math.round(Number(v)) + `%`;
            });
            uiManager.bind(`activeDisplay`, `domainState.activeUsers`, (v) => {
                const lang = (window.mySimulation && window.mySimulation.language) ? window.mySimulation.language : `en`;
                const n = Math.round(Number(v) * 1000);
                return lang === `es` ? n.toLocaleString(`de-DE`) : n.toLocaleString(`en-US`);
            });
            uiManager.bind(`contribDisplay`, `domainState.contribution`, (v) => {
                const card = document.querySelector(`.nairasim-card-contrib`);
                if (card) {
                    card.classList.toggle(`nairasim-contrib-positive`, Number(v) >= 0);
                    card.classList.toggle(`nairasim-contrib-negative`, Number(v) < 0);
                }
                return self._fmtNaira(Number(v));
            });
            uiManager.bind(`trustDisplay`, `domainState.trust`, (v) => {
                const card = document.querySelector(`.nairasim-card-trust`);
                if (card) card.classList.toggle(`nairasim-trust-low`, Number(v) < 30);
                return Math.round(Number(v));
            });
            uiManager.bind(`budgetDisplay`, `domainState.budgetUsed`, (v) => {
                return self._fmtNairaB(Number(v)) + ` / ` + self._fmtNairaB(self.LAUNCH_BUDGET);
            });

            // Live launch-budget allocation total (must hit NGN 1.2B).
            const allocIds = [`floatInput`, `recruitInput`, `channelBuildInput`, `educationInput`];
            const allocReadout = document.getElementById(`allocReadout`);
            const recompute = function() {
                let total = 0;
                allocIds.forEach((id) => {
                    const el = document.getElementById(id);
                    if (el) total += (parseFloat(el.value) || 0);
                });
                total = Math.round(total * 100) / 100;
                if (allocReadout) allocReadout.textContent = total.toFixed(2);
                const bar = document.querySelector(`.nairasim-alloc-readout`);
                if (bar) bar.style.color = (Math.abs(total - self.LAUNCH_BUDGET) > 0.001) ? `#ff7d6b` : ``;
            };
            allocIds.forEach((id) => {
                const el = document.getElementById(id);
                if (el) el.addEventListener(`input`, recompute);
            });
            recompute();
        }

        getChartConfig() {
            return {
                nairaChart: {
                    type: `line`,
                    data: {
                        labels: [],
                        datasets: [
                            {
                                label: window.mySimulation.t(`legend_reach`),
                                data: [],
                                borderColor: `#f7b733`,
                                backgroundColor: `rgba(247,183,51,0.14)`,
                                borderWidth: 3,
                                fill: true,
                                tension: 0.25,
                                pointRadius: 5,
                                pointBackgroundColor: `#f7b733`,
                                yAxisID: `y`
                            },
                            {
                                label: window.mySimulation.t(`legend_trust`),
                                data: [],
                                borderColor: `#c79bff`,
                                backgroundColor: `rgba(199,155,255,0.10)`,
                                borderWidth: 2,
                                fill: false,
                                tension: 0.25,
                                pointRadius: 4,
                                pointBackgroundColor: `#c79bff`,
                                yAxisID: `y`
                            },
                            {
                                label: window.mySimulation.t(`legend_contribution`),
                                data: [],
                                borderColor: `#7ad19b`,
                                backgroundColor: `rgba(122,209,155,0.08)`,
                                borderWidth: 2,
                                borderDash: [5, 4],
                                fill: false,
                                tension: 0.25,
                                pointRadius: 4,
                                pointBackgroundColor: `#7ad19b`,
                                yAxisID: `y1`
                            }
                        ]
                    },
                    options: {
                        responsive: true,
                        maintainAspectRatio: false,
                        plugins: {
                            legend: { position: `bottom`, labels: { color: `#bcd6c3`, boxWidth: 14 } },
                            title: { display: false }
                        },
                        scales: {
                            y: {
                                beginAtZero: true, max: 100, position: `left`,
                                ticks: { color: `#93b4a0` }, grid: { color: `rgba(255,255,255,0.06)` },
                                title: { display: true, text: window.mySimulation.t(`axis_reachtrust`), color: `#93b4a0` }
                            },
                            y1: {
                                position: `right`,
                                ticks: { color: `#7ad19b` }, grid: { drawOnChartArea: false },
                                title: { display: true, text: window.mySimulation.t(`axis_naira`), color: `#7ad19b` }
                            },
                            x: {
                                ticks: { color: `#93b4a0` }, grid: { color: `rgba(255,255,255,0.04)` },
                                title: { display: true, text: window.mySimulation.t(`axis_round`), color: `#93b4a0` }
                            }
                        }
                    }
                }
            };
        }

        getChartData(state) {
            const ds = state.domainState;
            const labels = ds.reachHistory.map((_, i) => (i === 0 ? window.mySimulation.t(`chart_start`) : window.mySimulation.t(`chart_round_prefix`) + i));
            return {
                nairaChart: {
                    labels: labels,
                    datasets: [
                        { data: ds.reachHistory },
                        { data: ds.trustHistory },
                        { data: ds.contribHistory }
                    ]
                }
            };
        }

        _composite(ds) {
            const reach = Math.round(ds.reach);
            const trust = Math.round(ds.trust);
            const contribution = Math.round(ds.contribution);
            const contribScore = Math.max(0, Math.min(100, ((contribution + 2100) / 4200) * 100));
            return Math.round(reach * 0.38 + (contribution >= 0 ? 100 : 0) * 0.22 + trust * 0.22 + contribScore * 0.18);
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            const ds = window.mySimulation.state.domainState;
            const reach = Math.round(ds.reach);
            const trust = Math.round(ds.trust);
            const contribution = Math.round(ds.contribution);
            const activeUsers = Math.round(ds.activeUsers * 1000);

            // Composite rewards the fundable thesis: genuine inclusion + positive unit economics + trust.
            const composite = this._composite(ds);

            const includes = reach >= 55 && !ds.bankedTheBanked;
            const sustainable = contribution >= 0;
            const trusted = trust >= 55;

            let performanceKey = `grade_withheld`;
            if (includes && sustainable && trusted && composite >= 72) performanceKey = `grade_released`;
            else if (ds.bankedTheBanked) performanceKey = `grade_banked`;
            else if (includes && !sustainable && ds.burningCash) performanceKey = `grade_unfundable`;
            else if (includes && sustainable) performanceKey = `grade_path`;
            else if (composite >= 50) performanceKey = `grade_mixed`;
            const met = includes && sustainable && trusted && composite >= 72;
            const performance = window.mySimulation.t(performanceKey);

            const insights = [];
            if (includes && sustainable && trusted) insights.push(window.mySimulation.t(`insight_released`));
            else if (ds.bankedTheBanked) insights.push(window.mySimulation.t(`insight_banked`));
            else insights.push(window.mySimulation.t(`insight_short`));

            if (ds.burningCash) insights.push(window.mySimulation.t(`insight_burn`));
            else if (sustainable) insights.push(window.mySimulation.t(`insight_sustainable`));
            if (ds.channelMismatch) insights.push(window.mySimulation.t(`insight_channel`));
            if (ds.agentStarved) insights.push(window.mySimulation.t(`insight_agent`));
            if (ds.funnelCollapsed) insights.push(window.mySimulation.t(`insight_kyc`));
            if (includes && trusted) insights.push(window.mySimulation.t(`insight_trusted`));

            return {
                reach: reach,
                trust: trust,
                contribution: contribution,
                activeUsers: activeUsers,
                includes: includes,
                sustainable: sustainable,
                trusted: trusted,
                bankedTheBanked: !!ds.bankedTheBanked,
                burningCash: !!ds.burningCash,
                channelMismatch: !!ds.channelMismatch,
                agentStarved: !!ds.agentStarved,
                funnelCollapsed: !!ds.funnelCollapsed,
                composite: composite,
                performance: performance,
                performanceKey: performanceKey,
                met: met,
                insights: insights
            };
        }

        formatCompletionMessage(summary) {
            const t = (k, v) => window.mySimulation.t(k, v);
            const s = summary || {};
            const score = (s.composite != null) ? s.composite : 0;
            const grade = s.performance || (s.performanceKey ? t(s.performanceKey) : ``);
            const badges = [];
            badges.push(`<span class="nairasim-cm-badge ` + (s.met ? `nairasim-cm-met` : `nairasim-cm-fail`) + `">` + (s.met ? t(`cm_met`) : t(`cm_not_met`)) + `</span>`);
            if (s.bankedTheBanked) badges.push(`<span class="nairasim-cm-badge nairasim-cm-fail">` + t(`cm_fail_banked`) + `</span>`);
            if (s.burningCash) badges.push(`<span class="nairasim-cm-badge nairasim-cm-fail">` + t(`cm_fail_burn`) + `</span>`);
            if (s.includes === false) badges.push(`<span class="nairasim-cm-badge nairasim-cm-fail">` + t(`cm_fail_reach`) + `</span>`);
            const kpi = (label, val) => `<div class="nairasim-cm-metric"><div class="nairasim-cm-metric-val">` + val + `</div><div class="nairasim-cm-metric-lbl">` + label + `</div></div>`;
            const kpis = kpi(t(`cm_reach`), (s.reach != null ? s.reach : 0) + `%`) + kpi(t(`cm_trust`), (s.trust != null ? s.trust : 0)) + kpi(t(`cm_contribution`), `₦` + (s.contribution != null ? s.contribution : 0)) + kpi(t(`cm_active`), (s.activeUsers != null ? s.activeUsers : 0));
            const insights = (s.insights || []).map((x) => `<li>` + x + `</li>`).join(``);
            return `<div class="nairasim-cm">`
                + `<div class="nairasim-cm-head"><div class="nairasim-cm-title">` + t(`cm_title`) + `</div>`
                + `<div class="nairasim-cm-scorewrap"><span class="nairasim-cm-score">` + score + `</span><span class="nairasim-cm-score-max">/100</span></div>`
                + `<div class="nairasim-cm-grade">` + grade + `</div>`
                + `<div class="nairasim-cm-badges">` + badges.join(``) + `</div></div>`
                + `<div class="nairasim-cm-metrics">` + kpis + `</div>`
                + `<div class="nairasim-cm-insights"><div class="nairasim-cm-insights-title">` + t(`cm_insights_title`) + `</div><ul>` + insights + `</ul></div>`
                + `</div>`;
        }

        getHint(state, results) {
            if (!results) return null;
            const ds = state.domainState;
            if (ds.bankedTheBanked) return window.mySimulation.t(`hint_banked`);
            if (ds.channelMismatch) return window.mySimulation.t(`hint_channel`);
            if (ds.agentStarved) return window.mySimulation.t(`hint_agent`);
            if (ds.burningCash) return window.mySimulation.t(`hint_burn`);
            if (ds.funnelCollapsed) return window.mySimulation.t(`hint_kyc`);
            if (ds.reach >= 55 && ds.contribution >= 0 && ds.trust >= 55) return window.mySimulation.t(`hint_strong`);
            return null;
        }

        getHistoryTableConfig() {
            const self = this;
            return [
                { key: `period`, label: `Round`, i18nKey: `col_round` },
                { key: `results.summary`, label: `Move`, i18nKey: `col_move` },
                { key: `results.reach`, label: `Reach`, i18nKey: `col_reach`, formatter: (v) => Math.round(v) + `%` },
                { key: `results.activeUsers`, label: `Active`, i18nKey: `col_active`, formatter: (v) => Math.round(v) + `k` },
                { key: `results.contribution`, label: `Contribution`, i18nKey: `col_contrib`, formatter: (v) => self._fmtNaira(Number(v)) },
                { key: `results.trust`, label: `Trust`, i18nKey: `col_trust`, formatter: (v) => Math.round(v) }
            ];
        }

